// Pi, the companion, and the road to 120, in the same pixel style as the Codex (art.ts): a small round creature
// with π on its belly that grows through five forms as the person keeps doing real things (never with a
// biomarker), and a winding road with twelve stations. Pure: rasters out.

import { Raster } from '../codex/art.ts'

const INK = '#0d0f12'
const TEAL = { l: '#8ff0df', b: '#2fbfa8', d: '#1b6f63' }
const CREAM = '#f4ead5'
const GOLD = '#f2b53a'
const PINK = '#ff8fab'
const LEAF = '#7bd88f'

export type PiForm = 0 | 1 | 2 | 3 | 4
export const PI_FORMS: ReadonlyArray<{ name: string; zh: string; at: number }> = [
  { name: 'egg', zh: '一颗蛋', at: 0 },
  { name: 'baby', zh: '小 Pi', at: 3 },
  { name: 'sprout', zh: '发芽的 Pi', at: 15 },
  { name: 'walker', zh: '出门走走的 Pi', at: 50 },
  { name: 'sage', zh: '百岁的 Pi', at: 150 },
]

export type PiMood = 'idle' | 'happy' | 'sleepy'

const memo = new Map<string, Raster>()

function piGlyph(r: Raster, cx: number, cy: number, col: string): void {
  r.rect(cx - 3, cy - 2, 7, 1, col)
  r.rect(cx - 2, cy - 1, 1, 4, col)
  r.rect(cx + 1, cy - 1, 1, 3, col)
  r.set(cx + 2, cy + 2, col)
}

function eyes(r: Raster, cx: number, cy: number, mood: PiMood, blink: boolean): void {
  if (blink || mood === 'sleepy') {
    r.rect(cx - 4, cy, 2, 1, INK)
    r.rect(cx + 2, cy, 2, 1, INK)
    return
  }
  if (mood === 'happy') {
    r.set(cx - 4, cy + 1, INK); r.set(cx - 3, cy, INK); r.set(cx - 2, cy + 1, INK)
    r.set(cx + 2, cy + 1, INK); r.set(cx + 3, cy, INK); r.set(cx + 4, cy + 1, INK)
    return
  }
  r.rect(cx - 4, cy - 1, 2, 2, INK)
  r.rect(cx + 2, cy - 1, 2, 2, INK)
  r.set(cx - 4, cy - 1, '#ffffff')
  r.set(cx + 2, cy - 1, '#ffffff')
}

/** Pi in one of its five forms, 28 × 28, at animation frame `frame` (bob and blink). */
export function piSprite(form: PiForm, mood: PiMood, frame: number): Raster {
  const bob = mood === 'sleepy' ? 0 : frame % 4 === 1 || frame % 4 === 2 ? 1 : 0
  const blink = frame % 16 === 7
  // Asleep: a small z drifts up and fades, in three steps.
  const z = mood === 'sleepy' ? frame % 6 < 2 ? 0 : frame % 6 < 4 ? 1 : 2 : 0
  const key = `${form}:${mood}:${bob}:${blink ? 1 : 0}:${z}`
  const hit = memo.get(key)
  if (hit) return hit
  const r = new Raster(28, 28)
  const cx = 14
  const cy = 16 - bob
  if (form === 0) {
    r.ellipse(cx, cy, 8, 10, CREAM)
    r.ellipse(cx - 2, cy - 4, 2, 3, '#ffffff')
    for (let x = cx - 5; x <= cx + 5; x += 1) r.set(x, cy + ((x % 2) === 0 ? -1 : 0), '#c9b48c')
    piGlyph(r, cx, cy + 4, TEAL.d)
    if (mood === 'happy') { r.set(cx - 9, cy - 8, GOLD); r.set(cx + 9, cy - 9, GOLD) }
    memo.set(key, r.outline())
    return r
  }
  const size = form === 1 ? 7 : form === 2 ? 8 : 9
  r.disc(cx, cy, size, TEAL.b)
  r.disc(cx - 2, cy - 3, size - 4, TEAL.l)
  r.disc(cx, cy + 1, size - 2, TEAL.b)
  r.ellipse(cx, cy + 4, size - 3, size - 5, '#e9fffa')
  piGlyph(r, cx, cy + 4, TEAL.d)
  eyes(r, cx, cy - 2, mood, blink)
  if (mood === 'happy') { r.set(cx - 6, cy + 1, PINK); r.set(cx + 6, cy + 1, PINK) }
  // feet
  r.rect(cx - 5, cy + size, 3, 1, TEAL.d)
  r.rect(cx + 3, cy + size, 3, 1, TEAL.d)
  if (form >= 2) {
    // a sprout on the head
    r.line(cx, cy - size - 1, cx, cy - size + 1, LEAF)
    r.ellipse(cx - 2, cy - size - 2, 2, 1, LEAF)
    r.ellipse(cx + 2, cy - size - 3, 2, 1, LEAF)
  }
  if (form >= 3) {
    // a scarf for the road
    r.rect(cx - size + 2, cy + 1, size * 2 - 3, 2, '#e5484d')
    r.rect(cx + size - 3, cy + 3, 2, 3, '#e5484d')
  }
  if (form >= 4) {
    // the sage: a halo of gold and a long white brow
    r.ring(cx, cy - size - 4, 3, GOLD)
    r.rect(cx - 6, cy - 4, 3, 1, '#ffffff')
    r.rect(cx + 4, cy - 4, 3, 1, '#ffffff')
  }
  if (mood === 'sleepy') {
    const zx = cx + 8 + z * 2
    const zy = cy - 8 - z * 3
    const col = z === 2 ? '#7f93ad' : '#cfe3ff'
    r.rect(zx, zy, 3, 1, col); r.set(zx + 1, zy + 1, col); r.rect(zx, zy + 2, 3, 1, col)
  }
  memo.set(key, r.outline())
  return r
}

export function formOf(actions: number): PiForm {
  let form: PiForm = 0
  PI_FORMS.forEach((row, i) => { if (actions >= row.at) form = i as PiForm })
  return form
}

/** The road to 120: twelve stations on a winding path, the reached ones lit (`lit[i]`), the flag at the end. */
export function roadSprite(width: number, lit: readonly boolean[], total = 12): Raster {
  const reached = lit.filter(Boolean).length
  const h = 26
  const r = new Raster(width, h, '#14202a')
  // hills
  for (let x = 0; x < width; x += 1) {
    const hill = Math.round(5 + Math.sin(x / 9) * 2 + Math.sin(x / 4.3) * 1)
    for (let y = h - hill; y < h; y += 1) r.set(x, y, y === h - hill ? '#2c4a3a' : '#1f3a2c')
  }
  // stars
  for (let i = 0; i < width / 6; i += 1) r.set((i * 37) % width, (i * 13) % 10, i % 3 === 0 ? '#9fb3c8' : '#5d6f82')
  const points: Array<[number, number]> = []
  for (let i = 0; i < total; i += 1) {
    const x = Math.round(4 + (i / (total - 1)) * (width - 9))
    const y = Math.round(13 + Math.sin(i * 1.1) * 5)
    points.push([x, y])
  }
  for (let i = 1; i < points.length; i += 1) {
    const [ax, ay] = points[i - 1] as [number, number]
    const [bx, by] = points[i] as [number, number]
    r.thick(ax, ay, bx, by, lit[i - 1] && lit[i] ? '#c9a46a' : '#3b4048', 2)
  }
  points.forEach(([x, y], i) => {
    const on = Boolean(lit[i])
    r.disc(x, y, 2, on ? GOLD : '#4b5566')
    if (on) r.set(x, y, '#fff7d6')
  })
  // the flag at 120
  const [fx, fy] = points[points.length - 1] as [number, number]
  r.rect(fx + 2, fy - 9, 1, 9, CREAM)
  r.rect(fx + 3, fy - 9, 4, 3, reached >= total ? GOLD : '#e5484d')
  return r.outline()
}

/** Where on the road (pixels) station `i` sits, for placing Pi and the station numbers. */
export function stationAt(width: number, i: number, total = 12): { x: number; y: number } {
  return { x: Math.round(4 + (i / (total - 1)) * (width - 9)), y: Math.round(13 + Math.sin(i * 1.1) * 5) }
}

/** A medal for an achievement: gold when earned, a dark outline when not yet. */
export function medal(earned: boolean, kind: number): Raster {
  const key = `medal:${earned ? 1 : 0}:${kind % 6}`
  const hit = memo.get(key)
  if (hit) return hit
  const ribbons = ['#e5484d', '#5b8def', '#3fb950', '#a371f7', '#d29922', '#39c5bb']
  const r = new Raster(14, 16)
  if (earned) {
    r.rect(4, 0, 2, 6, ribbons[kind % 6] as string)
    r.rect(8, 0, 2, 6, ribbons[(kind + 2) % 6] as string)
    r.disc(7, 10, 5, GOLD)
    r.disc(7, 10, 3, '#ffe896')
    r.set(7, 10, '#fff7d6')
  } else {
    r.rect(4, 0, 2, 6, '#3b4048')
    r.rect(8, 0, 2, 6, '#3b4048')
    r.ring(7, 10, 5, '#4b5566')
  }
  memo.set(key, r.outline())
  return r
}

files.hooks/ui/band.tsx:
// The one prompt slot in the workday (docs/codex-design.md §2), here the row above Claude Code's prompt. Two
// kinds only: the stand-up reminder (wristband owners who turned it on, ≥90 min of continuous use, a Claude turn
// running ≥60 s; no reward, no health number, no time promise) and, on a reveal day, 「有一张实验卡可以翻了」.
// Nothing in 演示模式. Ported from the web's slot-rules.ts and slot.ts.

import type { RenderElement } from 'claude-code'

import type { Els } from './types.ts'

export const SITTING_MIN = 90
export const TURN_MS = 60_000
/** A pause this long counts as having got up. */
export const BREAK_MS = 5 * 60_000
/** A stand-up line nobody answered folds away after this; it still counted as shown. */
export const STANDUP_VISIBLE_MS = 3 * 60_000

export type Activity = { since: number; last: number }

/** One sign of the person at the keyboard: a long enough pause before it starts a new sitting. */
export function noteInput(now: number, prev: Activity | null): Activity {
  if (!prev || now - prev.last >= BREAK_MS) return { since: now, last: now }
  return { since: prev.since, last: now }
}

/** Minutes of continuous use; 0 after a pause of 5 minutes or more. */
export function sittingMinutes(activity: Activity | null, now: number): number {
  if (!activity || now - activity.last >= BREAK_MS) return 0
  return (now - activity.since) / 60_000
}

export function sittingZh(minutes: number): string {
  const m = Math.max(0, Math.round(minutes))
  const hours = Math.floor(m / 60)
  const rest = m % 60
  if (hours === 0) return `${rest} 分钟`
  return rest === 0 ? `${hours} 小时` : `${hours} 小时 ${rest} 分`
}

export type SlotView = { standup: boolean; standups_left: number; reveal: null | { ref: string; text_zh: string }; quiet: string | null }
export type BandPrompt = { kind: 'standup' | 'reveal' | 'news' | 'welcome' | 'today'; ref: string; text: string; at: number }

export function nextBand(input: { enabled: boolean; presentation: boolean; slot: SlotView | null; sitting: number; turnMs: number; now: number }): BandPrompt | null {
  if (!input.enabled || input.presentation || !input.slot) return null
  if (input.slot.reveal) return { kind: 'reveal', ref: input.slot.reveal.ref, text: input.slot.reveal.text_zh, at: input.now }
  if (input.slot.standup && input.sitting >= SITTING_MIN && input.turnMs >= TURN_MS) {
    return { kind: 'standup', ref: '', text: `已经坐了 ${sittingZh(input.sitting)}。起来走两分钟？`, at: input.now }
  }
  return null
}

export type BandActions = {
  todayOpen: () => void
  todayLater: () => void
  welcomeOpen: () => void
  welcomeLater: () => void
  newsOpen: (ref: string) => void
  newsLater: (ref: string) => void
  standupOk: () => void
  standupOff: () => void
  revealOpen: (ref: string) => void
  revealLater: (ref: string) => void
}

export function bandTree(E: Els, prompt: BandPrompt, act: BandActions): RenderElement {
  const { Box, Text, Button } = E
  const buttons = prompt.kind === 'today'
    ? [
      <Button key="lp-today-go" plain hotkey="y" label="打开" onPress={() => act.todayOpen()} />,
      <Button key="lp-today-later" plain hotkey="n" dimColor label="稍后" onPress={() => act.todayLater()} />,
    ]
    : prompt.kind === 'welcome'
    ? [
      <Button key="lp-welcome-go" plain hotkey="y" label="打开" onPress={() => act.welcomeOpen()} />,
      <Button key="lp-welcome-later" plain hotkey="n" dimColor label="知道了" onPress={() => act.welcomeLater()} />,
    ]
    : prompt.kind === 'news'
    ? [
      <Button key="lp-news-go" plain hotkey="y" label="去看" onPress={() => act.newsOpen(prompt.ref)} />,
      <Button key="lp-news-later" plain hotkey="n" dimColor label="稍后" onPress={() => act.newsLater(prompt.ref)} />,
    ]
    : prompt.kind === 'standup'
    ? [
      <Button key="lp-standup-ok" plain hotkey="y" label="好" onPress={() => act.standupOk()} />,
      <Button key="lp-standup-off" plain hotkey="n" dimColor label="今天别提醒了" onPress={() => act.standupOff()} />,
    ]
    : [
      <Button key="lp-reveal-go" plain hotkey="y" label="去看" onPress={() => act.revealOpen(prompt.ref)} />,
      <Button key="lp-reveal-later" plain hotkey="n" dimColor label="稍后" onPress={() => act.revealLater(prompt.ref)} />,
    ]
  return (
    <Box gap={2}>
      <Box flexShrink={1}>
        <Text wrap="truncate-end">{prompt.text}</Text>
      </Box>
      <Box flexShrink={0} gap={1}>{buttons}</Box>
    </Box>
  )
}

files.hooks/sys/globals.ts:
// Web globals the core calls that the mod environment lacks: fetch (through the engine's network),
// console (into the engine's debug log) and queueMicrotask.

import { host } from './host.ts'
import { installTimerGlobals } from './timers.ts'

class FetchHeaders {
  private map = new Map<string, string>()
  constructor(init?: Record<string, string>) {
    for (const [key, value] of Object.entries(init ?? {})) this.map.set(key.toLowerCase(), value)
  }
  get(name: string): string | null {
    return this.map.get(name.toLowerCase()) ?? null
  }
  has(name: string): boolean {
    return this.map.has(name.toLowerCase())
  }
  forEach(fn: (value: string, key: string) => void): void {
    for (const [key, value] of this.map) fn(value, key)
  }
}

function headersOf(init: unknown): Record<string, string> {
  if (!init) return {}
  if (Array.isArray(init)) return Object.fromEntries(init as Array<[string, string]>)
  if (typeof (init as { forEach?: unknown }).forEach === 'function' && !(init instanceof Object && Object.getPrototypeOf(init) === Object.prototype)) {
    const out: Record<string, string> = {}
    ;(init as { forEach: (fn: (value: string, key: string) => void) => void }).forEach((value, key) => { out[key] = value })
    return out
  }
  return Object.fromEntries(Object.entries(init as Record<string, unknown>).map(([key, value]) => [key, String(value)]))
}

export async function hostFetch(input: string | URL | { url: string }, init: { method?: string; headers?: unknown; body?: unknown; signal?: AbortSignal } = {}) {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url
  if (init.signal?.aborted) throw Object.assign(new Error('The operation was aborted'), { name: 'AbortError' })
  const body = init.body === undefined || init.body === null ? undefined : typeof init.body === 'string' ? init.body : JSON.stringify(init.body)
  const answer = await host().io.fetch(url, { method: init.method ?? 'GET', headers: headersOf(init.headers), ...(body !== undefined ? { body } : {}) })
  const text = answer.text
  return {
    status: answer.status,
    ok: answer.ok,
    statusText: String(answer.status),
    url,
    headers: new FetchHeaders(answer.headers),
    text: async () => text,
    json: async () => JSON.parse(text) as unknown,
    arrayBuffer: async () => new TextEncoder().encode(text).buffer,
  }
}

export function installGlobals(): void {
  installTimerGlobals()
  const g = globalThis as Record<string, unknown>
  if (typeof g.fetch !== 'function') g.fetch = hostFetch
  if (typeof g.queueMicrotask !== 'function') g.queueMicrotask = (fn: () => void) => void Promise.resolve().then(fn)
  if (typeof g.console !== 'object' || g.console === null) {
    const line = (level: string) => (...parts: unknown[]) => {
      try {
        host().io.log(`${level}: ${parts.map((part) => (typeof part === 'string' ? part : JSON.stringify(part))).join(' ')}`)
      } catch {
        // before the host is installed
      }
    }
    g.console = { log: line('log'), info: line('info'), warn: line('warn'), error: line('error'), debug: line('debug') }
  }
}

files.hooks/sys/timers.ts:
// setTimeout and friends on the engine's clock: the mod environment has no timers of its own. The host
// installs `schedule` (backed by $.clock.after) at session start; until then a timer simply never fires.

type Cancel = () => void
type Scheduler = (ms: number, fn: () => void) => Cancel

let schedule: Scheduler | null = null
let nextId = 1
const live = new Map<number, Cancel>()

export function installScheduler(fn: Scheduler): void {
  schedule = fn
}

export function setTimeout(fn: (...args: unknown[]) => void, ms = 0, ...args: unknown[]): number {
  const id = nextId++
  if (!schedule) return id
  const cancel = schedule(Math.max(0, ms), () => {
    live.delete(id)
    fn(...args)
  })
  live.set(id, cancel)
  return id
}

export function clearTimeout(id: unknown): void {
  if (typeof id !== 'number') return
  live.get(id)?.()
  live.delete(id)
}

export function setInterval(fn: (...args: unknown[]) => void, ms = 0, ...args: unknown[]): number {
  const id = nextId++
  const tick = (): void => {
    if (!live.has(id)) return
    fn(...args)
    if (live.has(id) && schedule) live.set(id, schedule(Math.max(1, ms), tick))
  }
  if (schedule) live.set(id, schedule(Math.max(1, ms), tick))
  return id
}

export function clearInterval(id: unknown): void {
  clearTimeout(id)
}

/** Make the Node globals the core calls exist. */
export function installTimerGlobals(): void {
  const g = globalThis as Record<string, unknown>
  // Only where the environment has none (the mod's); a Node dev host keeps its own.
  if (typeof g.setTimeout !== 'function') {
    g.setTimeout = setTimeout
    g.clearTimeout = clearTimeout
    g.setInterval = setInterval
    g.clearInterval = clearInterval
  }
  if (typeof g.setImmediate !== 'function') g.setImmediate = (fn: () => void) => setTimeout(fn, 0)
  const signal = AbortSignal as unknown as Record<string, unknown>
  if (typeof signal.timeout !== 'function') {
    signal.timeout = (ms: number) => {
      const controller = new AbortController()
      setTimeout(() => controller.abort(Object.assign(new Error('The operation timed out'), { name: 'TimeoutError' })), ms)
      return controller.signal
    }
  }
  if (typeof signal.any !== 'function') {
    signal.any = (signals: AbortSignal[]) => {
      const controller = new AbortController()
      for (const one of signals) {
        if (one.aborted) {
          controller.abort((one as unknown as { reason?: unknown }).reason)
          break
        }
        one.addEventListener('abort', () => controller.abort((one as unknown as { reason?: unknown }).reason))
      }
      return controller.signal
    }
  }
}

files.hooks/sys/vfs.ts:
// The ported core reads and writes files synchronously, as it did under Node. A mod reaches the disk only
// asynchronously, through the engine. So each operation runs against an in-memory copy: `sync` loads the
// roots the core uses (the LongPi home, the method library's tables, the mod's own data) before the
// operation, the core works on the copy, and `flush` writes what changed back after it. A read outside the
// loaded roots is a miss: it behaves as "no such file" and is logged, never guessed.

import { host, type Io } from './host.ts'
import { dirname, normalize } from './path.ts'
import { toBase64 } from './buffer.ts'

type FileNode = {
  /** null: the file exists on disk but was not loaded (too big, or binary). */
  text: string | null
  /** Bytes written by the core that are not text (the zip export). */
  bytes: Uint8Array | null
  size: number
  mtimeMs: number
  dirty: boolean
  onDisk: boolean
  mode: number | null
}

export type RootSpec = {
  path: string
  /** Load everything below (default), or only the listed files. */
  recursive?: boolean
  /** Sub-directories (names) not to walk; they are known to exist but stay unlisted. */
  skipDirs?: readonly string[]
  /** Files larger than this stay unloaded (text null). */
  maxBytes?: number
  /** Read once per session (the mod's own shipped files): later syncs skip it. */
  once?: boolean
}

const TEXT_EXT = /\.(json|jsonl|md|txt|csv|tsv|yml|yaml|ics|html|py|toml|ts|js|mjs|xml|svg|log|tmp)$|^[^.]+$/i
const DEFAULT_MAX = 6 * 1024 * 1024

class Vfs {
  files = new Map<string, FileNode>()
  dirs = new Set<string>()
  /** Directories whose children are all known. */
  listed = new Set<string>()
  newDirs = new Set<string>()
  deleted = new Set<string>()
  chmods = new Map<string, number>()
  misses = new Set<string>()
  roots: RootSpec[] = []
  private lock: Promise<unknown> = Promise.resolve()

  /** True while an operation holds the copy. */
  busy = false

  /** Serialises operations: one core operation at a time sees and changes the copy. */
  exclusive<T>(fn: () => Promise<T>): Promise<T> {
    const guarded = async (): Promise<T> => {
      this.busy = true
      try {
        return await fn()
      } finally {
        this.busy = false
      }
    }
    const run = this.lock.then(guarded, guarded)
    this.lock = run.catch(() => undefined)
    return run
  }

  addRoot(spec: RootSpec): void {
    const path = normalize(spec.path)
    if (this.roots.some((root) => root.path === path)) return
    this.roots.push({ ...spec, path })
  }

  isKnownDir(path: string): boolean {
    return this.dirs.has(path)
  }

  /** The nearest listed ancestor decides whether a missing path is truly absent. */
  private authoritative(path: string): boolean {
    let dir = dirname(path)
    for (;;) {
      if (this.listed.has(dir)) return true
      if (this.dirs.has(dir) && !this.listed.has(dir)) return false
      const up = dirname(dir)
      if (up === dir) return false
      dir = up
    }
  }

  noteMiss(path: string): void {
    if (this.authoritative(path)) return
    if (!this.misses.has(path)) {
      this.misses.add(path)
      try {
        host().io.log(`vfs miss: ${path}`)
      } catch {
        // no host yet
      }
    }
  }

  ensureDirChain(path: string, created: boolean): void {
    let dir = normalize(path)
    const chain: string[] = []
    while (!this.dirs.has(dir)) {
      chain.push(dir)
      const up = dirname(dir)
      if (up === dir) break
      dir = up
    }
    for (const item of chain) {
      this.dirs.add(item)
      this.listed.add(item)
      if (created) this.newDirs.add(item)
    }
  }

  /** Load or refresh one root from disk. */
  async syncRoot(io: Io, spec: RootSpec): Promise<void> {
    const stat = await io.stat(spec.path)
    if (!stat) {
      // The root is absent on disk; whatever the core created in memory stays.
      for (const path of [...this.files.keys()]) {
        const node = this.files.get(path)
        if (node && node.onDisk && path.startsWith(`${spec.path}/`) && !node.dirty) this.files.delete(path)
      }
      if (!this.newDirs.has(spec.path)) {
        this.dirs.delete(spec.path)
        this.listed.delete(spec.path)
      }
      // Its parent is authoritative for it now.
      this.dirs.add(dirname(spec.path))
      this.listed.add(dirname(spec.path))
      return
    }
    if (stat.kind === 'file') {
      await this.syncFile(io, spec.path, stat.size, stat.mtimeMs, spec.maxBytes ?? DEFAULT_MAX)
      this.ensureDirChain(dirname(spec.path), false)
      return
    }
    this.ensureDirChain(spec.path, false)
    if (spec.recursive === false) return
    await this.walk(io, spec.path, spec)
  }

  private async walk(io: Io, dir: string, spec: RootSpec): Promise<void> {
    let entries
    try {
      entries = await io.list(dir)
    } catch {
      return
    }
    this.dirs.add(dir)
    this.listed.add(dir)
    const seen = new Set<string>()
    for (const entry of entries) {
      const path = `${dir}/${entry.name}`
      seen.add(path)
      if (this.deleted.has(path)) continue
      if (entry.kind === 'directory') {
        this.dirs.add(path)
        if (spec.skipDirs?.includes(entry.name) && dir === spec.path) {
          this.listed.delete(path)
          continue
        }
        await this.walk(io, path, spec)
      } else if (entry.kind === 'file') {
        await this.syncFile(io, path, entry.size, entry.mtimeMs, spec.maxBytes ?? DEFAULT_MAX)
      }
    }
    // Files gone from disk (and not written by the core since) are gone here too.
    for (const path of [...this.files.keys()]) {
      if (dirname(path) !== dir || seen.has(path)) continue
      const node = this.files.get(path)
      if (node && node.onDisk && !node.dirty) this.files.delete(path)
    }
  }

  private async syncFile(io: Io, path: string, size: number, mtimeMs: number, maxBytes: number): Promise<void> {
    const node = this.files.get(path)
    const loaded = node ? node.text !== null || node.bytes !== null : false
    if (node && (node.dirty || (loaded && node.mtimeMs === mtimeMs && node.size === size))) return
    if (this.deleted.has(path)) return
    const loadable = size <= maxBytes && TEXT_EXT.test(path.slice(path.lastIndexOf('/') + 1))
    let text: string | null = null
    if (loadable) {
      try {
        text = await io.read(path)
      } catch {
        text = null
      }
    }
    this.files.set(path, { text, bytes: null, size, mtimeMs, dirty: false, onDisk: true, mode: null })
  }

  /** Load one file or directory on demand (an async caller about to run sync code that reads it). */
  async ensure(io: Io, path: string, options: { recursive?: boolean; maxBytes?: number } = {}): Promise<void> {
    const at = normalize(path)
    const stat = await io.stat(at)
    if (!stat) {
      this.ensureDirChain(dirname(at), false)
      this.listed.add(dirname(at))
      return
    }
    if (stat.kind === 'file') {
      this.ensureDirChain(dirname(at), false)
      await this.syncFile(io, at, stat.size, stat.mtimeMs, options.maxBytes ?? DEFAULT_MAX)
      return
    }
    this.ensureDirChain(at, false)
    if (options.recursive) await this.walk(io, at, { path: at, maxBytes: options.maxBytes })
    else {
      const entries = await io.list(at)
      this.listed.add(at)
      for (const entry of entries) {
        const child = `${at}/${entry.name}`
        if (entry.kind === 'directory') this.dirs.add(child)
        else if (entry.kind === 'file' && !this.files.has(child)) {
          this.files.set(child, { text: null, bytes: null, size: entry.size, mtimeMs: -1, dirty: false, onDisk: true, mode: null })
        }
      }
    }
  }

  /**
   * One process walks a large read-only tree (the method library) and returns its listing, with the text of
   * the files `include` names; far faster than a listing call per directory. False when no Python ran.
   */
  async bulkLoad(io: Io, python: string, root: string, include: string, maxBytes = 512 * 1024): Promise<boolean> {
    const script = [
      'import json,os,re,sys',
      'root,inc,cap=sys.argv[1],re.compile(sys.argv[2]),int(sys.argv[3])',
      'out=[]',
      'for d,ds,fs in os.walk(root):',
      ' ds[:]=[x for x in ds if not x.startswith(".") and x!="__pycache__"]',
      ' out.append({"p":d,"k":"d"})',
      ' for f in fs:',
      '  p=os.path.join(d,f)',
      '  try: st=os.stat(p)',
      '  except OSError: continue',
      '  e={"p":p,"k":"f","s":st.st_size,"m":int(st.st_mtime*1000)}',
      '  if inc.search(f) and st.st_size<=cap:',
      '   try: e["t"]=open(p,encoding="utf-8").read()',
      '   except Exception: pass',
      '  out.append(e)',
      'sys.stdout.write(json.dumps(out,ensure_ascii=False))',
    ].join('\n')
    let result
    try {
      result = await io.run([python, '-c', script, root, include, String(maxBytes)], { timeoutMs: 60_000 })
    } catch {
      return false
    }
    if (result.exitCode !== 0) return false
    let rows: Array<{ p: string; k: 'd' | 'f'; s?: number; m?: number; t?: string }>
    try {
      rows = JSON.parse(result.stdout) as typeof rows
    } catch {
      return false
    }
    this.ensureDirChain(root, false)
    for (const row of rows) {
      if (row.k === 'd') {
        this.dirs.add(row.p)
        this.listed.add(row.p)
        continue
      }
      const prior = this.files.get(row.p)
      if (prior?.dirty) continue
      this.files.set(row.p, { text: typeof row.t === 'string' ? row.t : null, bytes: null, size: row.s ?? 0, mtimeMs: row.m ?? 0, dirty: false, onDisk: true, mode: null })
    }
    return true
  }

  private done = new Set<string>()

  async sync(io: Io): Promise<void> {
    for (const root of this.roots) {
      if (root.once && this.done.has(root.path)) continue
      await this.syncRoot(io, root)
      if (root.once) this.done.add(root.path)
    }
  }

  /** Whether the core wrote something not yet on disk. */
  hasPending(): boolean {
    if (this.deleted.size > 0 || this.newDirs.size > 0 || this.chmods.size > 0) return true
    for (const node of this.files.values()) if (node.dirty) return true
    return false
  }

  async flush(io: Io): Promise<void> {
    const removals = [...this.deleted]
    if (removals.length > 0) {
      await io.run(['rm', '-rf', '--', ...removals]).catch(() => undefined)
      this.deleted.clear()
    }
    const mk = [...this.newDirs].filter((dir) => this.dirs.has(dir)).sort((a, b) => a.length - b.length)
    if (mk.length > 0) {
      await io.run(['mkdir', '-p', '--', ...mk]).catch(() => undefined)
      this.newDirs.clear()
    }
    for (const [path, node] of this.files) {
      if (!node.dirty) continue
      if (node.bytes) {
        const tmp = `${path}.b64tmp`
        await io.write(tmp, toBase64(node.bytes))
        await io.run(['python3', '-c', 'import base64,sys;open(sys.argv[2],"wb").write(base64.b64decode(open(sys.argv[1]).read()))', tmp, path]).catch(() => undefined)
        await io.run(['rm', '-f', '--', tmp]).catch(() => undefined)
      } else {
        await io.write(path, node.text ?? '')
      }
      node.dirty = false
      node.onDisk = true
      const stat = await io.stat(path).catch(() => null)
      if (stat) {
        node.mtimeMs = stat.mtimeMs
        node.size = stat.size
      }
    }
    if (this.chmods.size > 0) {
      const byMode = new Map<number, string[]>()
      for (const [path, mode] of this.chmods) byMode.set(mode, [...(byMode.get(mode) ?? []), path])
      this.chmods.clear()
      for (const [mode, paths] of byMode) await io.run(['chmod', mode.toString(8), ...paths]).catch(() => undefined)
    }
  }

  children(dir: string): Array<{ name: string; kind: 'file' | 'directory' }> {
    const prefix = dir === '/' ? '/' : `${dir}/`
    const out = new Map<string, 'file' | 'directory'>()
    for (const path of this.files.keys()) {
      if (!path.startsWith(prefix)) continue
      const rest = path.slice(prefix.length)
      const slash = rest.indexOf('/')
      if (slash < 0) out.set(rest, 'file')
      else out.set(rest.slice(0, slash), 'directory')
    }
    for (const path of this.dirs) {
      if (!path.startsWith(prefix) || path === dir) continue
      const rest = path.slice(prefix.length)
      const slash = rest.indexOf('/')
      out.set(slash < 0 ? rest : rest.slice(0, slash), 'directory')
    }
    return [...out.entries()].map(([name, kind]) => ({ name, kind })).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
  }

  remove(path: string): void {
    const prefix = `${path}/`
    let wasOnDisk = false
    const node = this.files.get(path)
    if (node) {
      wasOnDisk = node.onDisk
      this.files.delete(path)
    }
    for (const [key, child] of [...this.files]) {
      if (key.startsWith(prefix)) {
        if (child.onDisk) wasOnDisk = true
        this.files.delete(key)
      }
    }
    if (this.dirs.has(path)) {
      wasOnDisk = wasOnDisk || !this.newDirs.has(path)
      for (const dir of [...this.dirs]) if (dir === path || dir.startsWith(prefix)) {
        this.dirs.delete(dir)
        this.listed.delete(dir)
        this.newDirs.delete(dir)
      }
    }
    if (wasOnDisk) this.deleted.add(path)
  }
}

export const vfs = new Vfs()

export type { FileNode }

