    active: (kind) => memoryFor(dataDirNow()).active(kind),
    apply: (ops, by) => memoryFor(dataDirNow()).apply(ops, by),
    digest: (opts) => memoryFor(dataDirNow()).digest(opts),
    safetyFlags: () => memoryFor(dataDirNow()).safetyFlags(),
  }
